-- ════════════════════════════════════════════════════════
-- 257 — Huitième recensement : « roulé à la main » relu sur les pages —
--       Holt's (six lignes), Helvada (la 51), Herr Lehmann
-- ────────────────────────────────────────────────────────
-- LA RÈGLE. Pas de cigare de machine : on ne met en gamme que ce qu'une
-- page lue dit roulé à la main. Trois points restaient soumis à la
-- relecture ; chacun a été relu en octobre 2026 sur les pages de la maison
-- et celles des détaillants (aucune page de Famous Smoke, Cigars
-- International, JR Cigars ni Thompson).
--
-- ── HOLT'S CIGAR COMPANY : QUATRE LIGNES SORTENT, DEUX RESTENT ─────
--   Herfdog       La page dit « Dominican-made boutique bundle » ; l'avis du
--                 personnel (22 août 2025) parle d'une petite fabrique et de
--                 rouleurs, jamais de la main. Sort.
--   Jalopy        La page dit « Manufactured in the Dominican Republic » ;
--                 l'avis du 25 août 2023, des fabriques de petites séries et
--                 des chutes de roulage. Sort.
--   Bottom Shelf  La page dit des tabacs « rolled in the Dominican
--                 Republic » ; l'avis du 30 mai 2025, des artisans qualifiés.
--                 Sort.
--   Par           La page ne dit rien du mode de fabrication et la maison n'a
--                 pas d'avis du personnel pour cette marque. Sort.
--   Bella Cuba    Un avis du personnel (5 août 2021, mis à jour le 30
--                 septembre 2025) dit les Bella Cuba « handmade in the
--                 Dominican Republic », au niveau de la marque ; la page de la
--                 Sumatra dit seulement « Dominican-crafted ». Reste, avec
--                 l'attribution écrite.
--   Angry Elf     Un avis du personnel (8 mars 2023) dit la marque
--                 « handcrafted entirely from long-filler tobaccos » ; la page
--                 de la Candela ne le dit pas. Reste, avec l'attribution.
--   L'histoire passe de vingt-quatre à vingt marques et dit « faites à la
--   main » là où une page le dit, en nommant les deux avis du personnel.
--   Les motifs des quatre sorties sont dans docs/recensement-8-exclus.md.
--
-- ── HELVADA : LA 51 RESTE, LA LIGNE DE MACHINE N'ÉTAIT PAS LA MAISON ───
-- La fiche écrivait que la maison lit la bague « Hecho a mano » du 51
-- comme une tripe façonnée à la machine sous une cape roulée à la main.
-- Aucune page de la maison ne le dit : la phrase vient d'une critique de
-- lecteur de Cigarworld.de (16 août 2020, « si j'ai bien compris »), reprise
-- sous le nom « schwizertrade » dans les avis de la page du 51 (25
-- décembre 2020). La maison est muette sur le roulage de toutes ses
-- lignes ; Cigarworld.de classe le 51, le 70, le 04, le 91, la Dark Line
-- (Brain, Skull, Hearth, ses longfillers roulés à Estelí) « totalmente a
-- mano », et la Medio Filler « totalmente a mano » à tripe déchirée. Les
-- trois lignes restent, chaque affirmation étant attribuée à Cigarworld.de ;
-- la divergence (lecteur 2020 / classement du détaillant) s'écrit.
-- Corrigés au passage : le 23 mai 2018 est une première dégustation, non un
-- lancement (daniel-schwizer.ch) ; la maison est à Ammerswil en 2026
-- (Kallern vient de la critique de 2020) ; Schwizer Trade GmbH n'est pas
-- datée de 2015, seul le but des fondateurs l'est : `founded` devient « Non
-- précisée ». « À base de medio tiempo » n'avait pas de page.
--
-- ── HERR LEHMANN : ON GARDE, LA NUANCE EST ÉCRITE ──────────────────
-- Netzwerk Südbaden (1er mars 2022) décrit un travail « en Handarbeit » : une
-- bande de cuir qui se referme sur du tabac coupé quand l'ouvrière actionne
-- une pédale, les poupées pressées vingt-quatre heures, la cape roulée à la
-- main le lendemain ; ni moteur ni courant n'y sont nommés. Dein Dorfleben dit
-- les cigares « von Hand gerollt » (2026) et « per Hand gewickelt » (13 août
-- 2021) ; Cigarworld.de les classe « totalmente a mano ». L'outil est donc
-- tenu pour un dispositif d'atelier mû par le pied, non pour une machine à
-- bouncher ; la fiche l'écrit, avec la divergence sur le tabac (feuilles
-- entières selon Cigarworld.de, tabac coupé selon Netzwerk Südbaden), et
-- corrige le nom du site partenaire (Dein Dorfleben, non Dein Dorfladen).
-- Reste ouvert : l'article ne dit pas ce que sont « les machines » reprises
-- aux Lehmann.
--
-- Rejouable : chaque remplacement est gardé par la présence du texte
-- ancien (comparé octet par octet), la gamme est relue en base et réécrite
-- en littéral dans chaque langue, les sceaux repassent à `machine`.
-- ════════════════════════════════════════════════════════

-- ── Holt's Cigar Company ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Vingt-quatre marques de son catalogue' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Vingt-quatre marques de son catalogue', 'Vingt marques de son catalogue'), `history`),
  `history_en` = IF(LOCATE(CAST('Twenty-four brands from its catalogue' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Twenty-four brands from its catalogue', 'Twenty brands from its catalogue'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Veinticuatro marcas de su catálogo' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Veinticuatro marcas de su catálogo', 'Veinte marcas de su catálogo'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Vierundzwanzig Marken seines Katalogs' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Vierundzwanzig Marken seines Katalogs', 'Zwanzig Marken seines Katalogs'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('其目录中的二十四个品牌' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '其目录中的二十四个品牌', '其目录中的二十个品牌'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('أربع وعشرون علامة من كتالوجها' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'أربع وعشرون علامة من كتالوجها', 'عشرون علامة من كتالوجها'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Holt''s Cigar Company';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La maison les dit faites en République dominicaine, sauf Benchmade, roulée à Estelí, au Nicaragua ;' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La maison les dit faites en République dominicaine, sauf Benchmade, roulée à Estelí, au Nicaragua ;', 'La maison les dit faites à la main en République dominicaine, sauf Benchmade, faite à la main à Estelí, au Nicaragua (pour Bella Cuba et Angry Elf, ce sont des avis de son personnel qui le disent) ;'), `history`),
  `history_en` = IF(LOCATE(CAST('The house says they are made in the Dominican Republic, except Benchmade, rolled in Estelí, Nicaragua' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The house says they are made in the Dominican Republic, except Benchmade, rolled in Estelí, Nicaragua', 'The house says they are handmade in the Dominican Republic, except Benchmade, handmade in Estelí, Nicaragua (for Bella Cuba and Angry Elf, it is its staff''s opinions that say so)'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La casa las dice hechas en la República Dominicana, salvo Benchmade, liada en Estelí, en Nicaragua' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La casa las dice hechas en la República Dominicana, salvo Benchmade, liada en Estelí, en Nicaragua', 'La casa las dice hechas a mano en la República Dominicana, salvo Benchmade, hecha a mano en Estelí, en Nicaragua (para Bella Cuba y Angry Elf, son opiniones de su personal las que lo dicen)'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Das Haus gibt sie als in der Dominikanischen Republik hergestellt an, außer Benchmade, die in Estelí in Nicaragua gerollt wird' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Das Haus gibt sie als in der Dominikanischen Republik hergestellt an, außer Benchmade, die in Estelí in Nicaragua gerollt wird', 'Das Haus gibt sie als in der Dominikanischen Republik von Hand gefertigt an, außer Benchmade, die in Estelí in Nicaragua von Hand gefertigt wird (bei Bella Cuba und Angry Elf sind es Einschätzungen seines Personals, die das sagen)'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('在多米尼加共和国制作，Benchmade除外，该款在尼加拉瓜的埃斯特利卷制' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '在多米尼加共和国制作，Benchmade除外，该款在尼加拉瓜的埃斯特利卷制', '在多米尼加共和国手工制作，Benchmade除外，该款在尼加拉瓜的埃斯特利手工制作（Bella Cuba与Angry Elf的这一说法出自其员工的评述）'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('صُنعت في جمهورية الدومينيكان، باستثناء Benchmade التي تُلَفّ في إستيلي بنيكاراغوا' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'صُنعت في جمهورية الدومينيكان، باستثناء Benchmade التي تُلَفّ في إستيلي بنيكاراغوا', 'صُنعت يدويًا في جمهورية الدومينيكان، باستثناء Benchmade التي تُصنع يدويًا في إستيلي بنيكاراغوا (أما في Bella Cuba وAngry Elf فآراء موظفيها هي التي تقول ذلك)'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Holt''s Cigar Company';

