  `gamme_es` = '[{"name":"All In!","color":"#C9A96E","force":"Mild","story":"Capa Connecticut Shade sobre tabacos dominicanos en Cuban sandwich, mezclando longfiller y shortfiller según una opinión del personal de Holt''s de abril de 2025, fuerza suave según Holt''s, que la dice hecha a mano en la República Dominicana; tres formatos con nombres tomados del póquer, en bundles de veinte: Flop (5 x 50), River (7 x 50) y Turn (6 x 50); en el catálogo de Holt''s en octubre de 2026.","vitolas":[],"wrapper":"Connecticut Shade"},{"name":"Amante","color":"#A0522D","force":"Mild-Medium","story":"Capa Sun Grown de Ecuador sobre un longfiller de tabacos dominicanos, fuerza suave a media según Holt''s, que la dice mezclada y hecha a mano en la República Dominicana por torcedores artesanales; un solo formato, el Toro 6 x 50, en un bundle de veinte; en el catálogo de Holt''s en octubre de 2026, agotada.","vitolas":[],"wrapper":"Sun Grown (Ecuador)"},{"name":"Angry Elf","color":"#C9A96E","force":"Mild","story":"Capa Candela sobre un longfiller de tabacos dominicanos y nicaragüenses, fuerza suave según Holt''s, que da la República Dominicana por país y dice la marca hecha a mano, enteramente en longfiller, en una opinión del personal de marzo de 2023; en bundles de veinte: Churchill (7 x 50), Robusto (5 x 50) y Toro (6 x 50); la marca tiene también versiones Connecticut, Maduro y Sun Grown, esta última dicha hecha a mano en una opinión del personal de noviembre de 2023, de fuerza media según la página; en el catálogo de Holt''s en octubre de 2026, agotada.","vitolas":[],"wrapper":"Candela"},{"name":"Argyle Cigars","color":"#C9A96E","force":"Mild","story":"Hecha a mano en la República Dominicana según Holt''s, capa Connecticut Shade sobre un longfiller de tabacos dominicanos, fuerza suave, en cofres de cedro de veinte, en siete formatos, de la Corona (5½ x 46) al Mayor (8 x 54); la página remite también a Argyle Maduro, Dark Corojo, Conundrum y White Glove; en el catálogo de Holt''s 