  `gamme_de` = '[{"name":"All In!","color":"#C9A96E","force":"Mild","story":"Deckblatt Connecticut Shade über dominikanischen Tabaken als Cuban sandwich, das laut einer Einschätzung des Holt''s-Personals vom April 2025 longfiller und shortfiller mischt, milde Stärke laut Holt''s, das angibt, sie werde in der Dominikanischen Republik von Hand gefertigt; drei nach dem Poker benannte Formate in bundles zu zwanzig: The Flop (5 x 50), The River (7 x 50) und The Turn (6 x 50); im Katalog von Holt''s im Oktober 2026.","vitolas":[],"wrapper":"Connecticut Shade"},{"name":"Amante","color":"#A0522D","force":"Mild-Medium","story":"Deckblatt Sun Grown aus Ecuador über einem longfiller aus dominikanischen Tabaken, milde bis mittlere Stärke laut Holt''s, das angibt, sie werde in der Dominikanischen Republik von handwerklichen Rollern gemischt und von Hand gefertigt; ein einziges Format, der Toro 6 x 50, in einem bundle zu zwanzig; im Katalog von Holt''s im Oktober 2026, ausverkauft.","vitolas":[],"wrapper":"Sun Grown (Ecuador)"},{"name":"Angry Elf","color":"#C9A96E","force":"Mild","story":"Deckblatt Candela über einem longfiller aus dominikanischen und nicaraguanischen Tabaken, milde Stärke laut Holt''s, das die Dominikanische Republik als Land angibt und die Marke in einer Einschätzung des Personals vom März 2023 als von Hand gefertigt und vollständig in longfiller bezeichnet; in bundles zu zwanzig: Churchill (7 x 50), Robusto (5 x 50) und Toro (6 x 50); die Marke führt auch Versionen Connecticut, Maduro und Sun Grown, Letztere in einer Einschätzung des Personals vom November 2023 als von Hand gefertigt bezeichnet, in mittlerer Stärke laut der Seite; im Katalog von Holt''s im Oktober 2026, ausverkauft.","vitolas":[],"wrapper":"Candela"},{"name":"Argyle Cigars","color":"#C9A96E","force":"Mild","story":"Laut Holt''s in der Dominikanischen Republik von Hand gefertigt, Deckblatt Connecticut Shade über einem longfiller aus dominikanischen Tabaken, milde Stärke, in Zedernholzkästchen zu zwanzig, in sieben Formaten von der Corona (5½ x 46) bis zum Mayor (8 x 54); die Seite verweist auch auf Argyle Maduro, Dark Corojo, Conundrum und White Glove; im Katalog von Holt''s im Oktober 2026 sechs von sieben Formaten vorrätig.","vitolas":[],"wrapper":"Connecticut Shade"},{"name":"Babalu","color":"#8B5A2B","force":"Medium","story":"Deckblatt Sun Grown in Lebkuchen-Farbton über einem longfiller aus dominikanischen und nicaraguanischen Tabaken, mittlere Stärke laut Holt''s, das angibt, sie werde in der Dominikanischen Republik von Hand gefertigt, in bundles zu zwanzig in vier Formaten: Churchill (7 x 50), Gordo (6 x 60), Robusto (5 x 50) und Toro (6 x 50); im Katalog von Holt''s im Oktober 2026, ausverkauft.","vitolas":[],"wrapper":"Sun Grown"},{"name":"Bella Cuba","color":"#A0522D","force":"Medium","story":"Deckblatt Sumatra über einer Einlage aus dominikanischen Tabaken als Cuban sandwich, mittlere Stärke laut Holt''s, darunter eine Einschätzung des Personals zur Version Connecticut (5. August 2021, am 30. September 2025 aktualisiert), die die Bella Cuba als in der Dominikanischen Republik von Hand gefertigt angibt, und die Seite der Sumatra, die sie als von dominikanischer Machart bezeichnet; in bundles zu zwanzig in vier Formaten: Churchill (7 x 50), Media Noche (6½ x 46), Robusto (5 x 50) und Toro (6½ x 52); im Katalog von Holt''s im Oktober 2026, ausverkauft.","vitolas":[],"wrapper":"Sumatra"},{"name":"Belleza","color":"#8B5A2B","force":"Mild-Medium","story":"Deckblatt Sun Grown in Lebkuchen-Farbton über einem gereiften dominikanischen longfiller, milde bis mittlere Stärke laut Holt''s, das angibt, sie werde in der Dominikanischen Republik von Handwerkern in Handarbeit gefertigt; ein einziges Format, der Toro 6 x 50, in einem bundle zu zwanzig; im Katalog von Holt''s im Oktober 2026, ausverkauft.","vitolas":[],"wrapper":"Sun Grown"},{"name":"Benchmade","color":"#8B5A2B","force":"Medium","story":"Drei Deckblätter zur Wahl, Natural, Maduro und Sun Grown, über einem longfiller aus dominikanischen, honduranischen und nicaraguanischen Tabaken, mittlere Stärke laut Holt''s, das angibt, sie werde in Estelí in Nicaragua in einer Fabrik gerollt, die es nicht nennt, in bundles zu zwanzig in fünf Formaten: Churchill, Gordo, Robusto, Toro und Torpedo; im Katalog von Holt''s im Oktober 2026, ausverkauft.","vitolas":[],"wrapper":"Natural, Maduro oder Sun Grown"},{"name":"Blenders Clearing House","color":"#8B5A2B","force":"Mild-Medium","story":"Deckblätter Connecticut (Natural) oder Habano (Maduro) aus Ecuador über einem longfiller aus dominikanischen und nicaraguanischen Tabaken, milde bis mittlere Stärke laut Holt''s, das angibt, sie werde in der Dominikanischen Republik von Hand gefertigt, in bundles zu zwanzig in sechs Formaten, vom Robusto (5 x 50) bis zum President (8 x 54), jedes mit zwei Deckblättern; im Katalog von Holt''s im Oktober 2026, ausverkauft.","vitolas":[],"wrapper":"Ecuador: Connecticut, Habano"},{"name":"Boardwalk","color":"#6B4226","force":"Medium","story":"Brasilianisches Deckblatt über einer Einlage aus dominikanischen und nicaraguanischen Tabaken als Cuban sandwich, mittlere Stärke laut Holt''s, das angibt, sie werde in der Dominikanischen Republik von Hand gefertigt, in bundles zu zwanzig in zwei Formaten, Robusto (5 x 50) und Toro (6 x 50); im Katalog von Holt''s im Oktober 2026, ausverkauft.","vitolas":[],"wrapper":"Brasilien"},{"name":"Casa Royale","color":"#C9A96E","force":"Mild-Medium","story":"Deckblatt Connecticut Shade über einem longfiller aus dominikanischen und nicaraguanischen Tabaken, milde bis mittlere Stärke laut Holt''s, das angibt, sie werde in der Dominikanischen Republik von Hand gefertigt, in Kisten zu zwanzig in vier Formaten: Churchill (7 x 50), Imperial (6 x 50), King (6 x 60) und Robusto (5 x 50); im Katalog von Holt''s im Oktober 2026, ausverkauft.","vitolas":[],"wrapper":"Connecticut Shade"},{"name":"Castano","color":"#A0522D","force":"Medium","story":"Deckblatt Sun Grown in Zi