 WHERE `name` = 'Herr Lehmann';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('une eau-de-vie de pomme, dit Dein Dorfladen ;' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'une eau-de-vie de pomme, dit Dein Dorfladen ;', 'une eau-de-vie de pomme, dit Dein Dorfleben ;'), `history`),
  `history_en` = IF(LOCATE(CAST('an apple brandy, says Dein Dorfladen;' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'an apple brandy, says Dein Dorfladen;', 'an apple brandy, says Dein Dorfleben;'), `history_en`),
  `history_es` = IF(LOCATE(CAST('un aguardiente de manzana, dice Dein Dorfladen;' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'un aguardiente de manzana, dice Dein Dorfladen;', 'un aguardiente de manzana, dice Dein Dorfleben;'), `history_es`),
  `history_de` = IF(LOCATE(CAST('einen Apfelbrand, so Dein Dorfladen;' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'einen Apfelbrand, so Dein Dorfladen;', 'einen Apfelbrand, so Dein Dorfleben;'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('与苹果白兰地，据Dein Dorfladen称；' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '与苹果白兰地，据Dein Dorfladen称；', '与苹果白兰地，据Dein Dorfleben称；'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وبراندي التفاح، بحسب Dein Dorfladen؛' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وبراندي التفاح، بحسب Dein Dorfladen؛', 'وبراندي التفاح، بحسب Dein Dorfleben؛'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Herr Lehmann';

UPDATE `brands` SET
  `source` = IF(LOCATE(CAST('en ligne Cigarworld et Dein Dorfladen' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'en ligne Cigarworld et Dein Dorfladen', 'en ligne Cigarworld et Dein Dorfleben'), `source`),
  `source` = IF(LOCATE(CAST('netzwerk-suedbaden.de « Zigarrenwerkstatt: Frisch gewickelt ' AS BINARY), CAST(`source` AS BINARY)) > 0, `source`, CONCAT(`source`, ' ; ', 'netzwerk-suedbaden.de « Zigarrenwerkstatt: Frisch gewickelt bei Herr Lehmann » (1er mars 2022 : « Sie stellen Zigarren in Handarbeit aus regionalem Tabak her » ; Umblatt posé sur un Lederband de la table à enrouler, « geschnittenen Tabak » déposé dessus, « bedient das Fußpedal », le Lederband se referme et libère la poupée ; poupées pressées 24 heures dans une Presse ; cape collée et enroulée à la main le lendemain à la table à rouler ; « erwarben sie deren Maschinen sowie deren Know-how » ; les mots Motor, Strom et elektrisch n''y figurent pas) ; deindorfleben.de « Herr Lehmann » (page about, 2026 : « von Hand gerollt », « sorgfältige Handarbeit » ; le site s''appelle DeinDorfleben) ; deindorfleben.de « Dorfladen Nr. 18: Zigarrenmanufaktur Herr Lehmann » (13 août 2021 : « Diese werden noch per Hand gewickelt ») ; herr-lehmann.com « Herr Lehmann » (2026 : partenaires en ligne « Cigarworld » et « Dein Dorfleben ») ; cigarworld.de « Herr Lehmann Zigarren » (légende TAM « mit ganzen Blättern », HAM « Einlage mit der Maschine, Deckblatt von Hand überrollt » ; No. 5, 7, 8 : TAM) ; cigarworld.de « Herr Lehmann No. 5 Schwarzwald » (« in einer historischen Holzform » ; Fabrication « Totalmente a mano - (longfiller) » ; catalogue depuis le 29 septembre 2016) ; gloriafumi.ch « 3 Fragen an Herr Lehmann » (reportage non daté : Rollerarbeitstische, Rollerinnen) ; waldrausch-magazin.de « Zeitloser Genuss » (20 mars 2020 : « Andere Fabriken produzierten maschinell »)')),
  `updated_at` = NOW()
 WHERE `name` = 'Herr Lehmann';

-- ── Les sceaux des champs réécrits, calculés depuis les colonnes françaises ──
INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `relecteur`, `maj`)
SELECT 'brands', b.`name`, c.champ, l.lang,
       SHA1(CASE c.champ WHEN 'history' THEN b.`history` ELSE b.`gamme` END), 'machine', NULL, NOW()
  FROM `brands` b
  JOIN (SELECT 'Holt''s Cigar Company' hote, 'gamme' champ
        UNION ALL SELECT 'Holt''s Cigar Company' hote, 'history' champ
        UNION ALL SELECT 'Helvada' hote, 'gamme' champ
        UNION ALL SELECT 'Helvada' hote, 'history' champ
        UNION ALL SELECT 'Herr Lehmann' hote, 'history' champ) c
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE c.hote = b.`name`
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `statut` = 'machine', `relecteur` = NULL, `maj` = NOW();

