UNION ALL SELECT 'Helvada', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Daniel Schwizer and Andrea Moor set themselves the goal in 2015 of making cigars their trade, says their website; on it, in October 2026, Schwizer Trade GmbH gives an address in Ammerswil, in the canton of Aargau (Switzerland). Daniel Schwizer recounts on his website that the master blender Kurt Brandt put their idea into practice for the Helvada brand, and that a small gathering tasted its cigars for the first time on 23 May 2018. Cigarworld.de presents Kurt Brandt as a blender who has already left his mark on Flor Real and Isthmus, after working for a long time in Costa Rica and then in Nicaragua.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Helvada'
