UNION ALL SELECT 'Helvada', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Daniel Schwizer y Andrea Moor se fijan en 2015 el objetivo de hacer del puro su oficio, dice su sitio; en él, en octubre de 2026, Schwizer Trade GmbH da una dirección en Ammerswil, en el cantón de Argovia (Suiza). Daniel Schwizer cuenta en su sitio que el master blender Kurt Brandt llevó su idea a la práctica para la marca Helvada, y que un pequeño grupo de personas probó por primera vez los puros de la marca el 23 de mayo de 2018. Cigarworld.de presenta a Kurt Brandt como un blender que ya ha dejado su huella en Flor Real e Isthmus, tras haber trabajado mucho tiempo en Costa Rica y luego en Nicaragua.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Helvada'
