UNION ALL SELECT 'Helvada', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Daniel Schwizer und Andrea Moor setzen sich 2015 zum Ziel, die Zigarre zu ihrem Beruf zu machen, so ihre Website; dort nennt Schwizer Trade GmbH im Oktober 2026 eine Adresse in Ammerswil im Kanton Aargau (Schweiz). Daniel Schwizer erzählt auf seiner Website, der Master Blender Kurt Brandt habe ihre Idee für die Marke Helvada umgesetzt, und eine kleine Runde habe die Zigarren der Marke am 23. Mai 2018 zum ersten Mal verkostet. Cigarworld.de stellt Kurt Brandt als Blender vor, der schon Flor Real und Isthmus geprägt hat, nachdem er lange in Costa Rica und dann in Nicaragua gearbeitet hat.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Helvada'
UNION ALL SELECT 'Helvada', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Daniel Schwizer und Andrea Moor gründen Schwizer Trade GmbH 2015 in Kallern, im Kanton Aargau (Schweiz). Am 23. Mai 2018 bringen sie ihre eigene Marke heraus, Helvada, deren Mischung Daniel Schwizer gemeinsam mit Kurt Brandt von Flor Real Cigars entwickelt hat, der in Nicaragua arbeitet, so das Haus.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Helvada'
UNION ALL SELECT 'Helvada', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Daniel Schwizer与Andrea Moor于2015年立志以雪茄为业，据其网站所述；在该网站上，Schwizer Trade GmbH于2026年10月给出了位于瑞士阿尔高州Ammerswil的地址。Daniel Schwizer在其网站上讲述，master blender Kurt Brandt将他们的构想落实到Helvada品牌上，而一小群人于2018年5月23日首次品尝了该品牌的雪茄。Cigarworld.de将Kurt Brandt介绍为一位已在Flor Real与Isthmus留下印记的blender，此前曾长期在哥斯达黎加、继而在尼加拉瓜工作。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Helvada'
