UNION ALL SELECT 'Helvada', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Das Haus nennt seine Fabrik nicht; seine Seiten geben Nicaragua als Herkunftsland an und sagen nicht, wie die Zigarren gerollt werden. Seine 51, im Format Gran Robusto, trägt ein Habano-Maduro-Deckblatt aus Ecuador über einem Umblatt aus Jalapa und einer Einlage aus Condega, Nicaragua, und dominikanischem Ligero, so das Haus. Cigarworld.de ordnet die Linie Helvada und die Dark Line als „totalmente a mano“ ein, als longfiller, und die Medio Filler als „totalmente a mano“ mit zerrissener Einlage; es sagt, die longfiller der Dark Line Hearth würden in Estelí gerollt. Ein Leser von Cigarworld.de liest am 16. August 2020 die Bauchbinde Hecho a mano der 51 als maschinell gefertigte Einlage unter einem von Hand gerollten Deckblatt, ohne sich dessen sicher zu sein, und die Seite der 51 des Hauses übernimmt diesen Text unter dem Namen „schwizertrade“ am 25. Dezember 2020.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Helvada'
