UNION ALL SELECT 'Herr Lehmann', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('En mars 2022, Netzwerk Südbaden décrit un atelier de la vieille ville de Lahr, où l''on travaille à la main (Handarbeit) : l''ouvrière pose du tabac coupé sur le liant étalé sur une bande de cuir, qui se referme quand elle actionne une pédale ; les poupées sont ensuite pressées vingt-quatre heures dans des moules de bois et la cape est roulée à la main le lendemain. L''article ne mentionne ni moteur ni courant, et dit que les repreneurs ont acquis les machines des Lehmann avec leur savoir-faire ; Dein Dorfleben dit les cigares roulés à la main.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Herr Lehmann'
UNION ALL SELECT 'Herr Lehmann', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('En mars 2022, Netzwerk Südbaden décrit un atelier de la vieille ville de Lahr où l''on forme la poupée avec une bande de cuir actionnée au pied, avant de la presser vingt-quatre heures dans des moules de bois et d''y poser la cape à la main.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Herr Lehmann'
UNION ALL SELECT 'Herr Lehmann', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('In March 2022, Netzwerk Südbaden describes a workshop in the old town of Lahr, where the work is done by hand (Handarbeit): the female worker lays cut tobacco on the binder spread on a leather band, which closes when she operates a pedal; the bunches are then pressed for twenty-four hours in wooden moulds and the wrapper is rolled by hand the next day. The article mentions neither a motor nor electric current, and says that the new owners acquired the Lehmanns'' machines together with their know-how; Dein Dorfleben says the cigars are rolled by hand.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Herr Lehmann'
UNION ALL SELECT 'Herr Lehmann', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('In March 2022, Netzwerk Südbaden describes a workshop in the old town of Lahr where the bunch is formed with a foot-operated leather band, before being pressed for twenty-four hours in wooden moulds and having the wrapper laid on by hand.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Herr Lehmann'
UNION ALL SELECT 'Herr Lehmann', 'es', 'histoire 3 (nouveau texte)', (LOCATE(CAST('En marzo de 2022, Netzwerk Südbaden describe un taller del casco antiguo de Lahr, donde se trabaja a mano (Handarbeit): la operaria coloca tabaco cortado sobre el capote extendido sobre una banda de cuero, que se cierra cuando acciona un pedal; los bonches se prensan después veinticuatro horas en moldes de madera y la capa se lía a mano al día siguiente. El artículo no menciona ni motor ni corriente eléctrica, y dice que los nuevos propietarios adquirieron las máquinas de los Lehmann con su saber hacer; Dein Dorfleben dice que los puros se lían a mano.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Herr Lehmann'
