UNION ALL SELECT 'Herr Lehmann', 'de', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Im März 2022 beschreibt Netzwerk Südbaden eine Werkstatt in der Lahrer Altstadt, in der von Hand gearbeitet wird (Handarbeit): Die Arbeiterin legt geschnittenen Tabak auf das auf einem Lederband ausgebreitete Umblatt, das sich schließt, wenn sie ein Pedal betätigt; die Wickel werden anschließend vierundzwanzig Stunden in Holzformen gepresst, und das Deckblatt wird am folgenden Tag von Hand gerollt. Der Artikel erwähnt weder Motor noch Strom und sagt, dass die neuen Inhaber die Maschinen der Lehmanns samt ihrem Know-how erworben haben; Dein Dorfleben sagt, die Zigarren würden von Hand gerollt.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Herr Lehmann'
UNION ALL SELECT 'Herr Lehmann', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Im März 2022 beschreibt Netzwerk Südbaden eine Werkstatt in der Lahrer Altstadt, in der der Wickel mit einem fußbetätigten Lederband geformt wird, bevor er vierundzwanzig Stunden in Holzformen gepresst und das Deckblatt von Hand aufgelegt wird.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Herr Lehmann'
UNION ALL SELECT 'Herr Lehmann', 'zh', 'histoire 3 (nouveau texte)', (LOCATE(CAST('2022年3月，Netzwerk Südbaden描述了拉尔老城区的一间工坊，那里以手工作业（Handarbeit）：女工把切碎的烟叶放在铺于皮革带上的茄套上，她踩动踏板时皮革带便合拢；茄束随后在木制模具中压制二十四小时，茄衣则在次日以手卷制。该文章未提及电机或电力，并称接手者连同其技艺一并买下了Lehmann家的机器；Dein Dorfleben称这些雪茄为手工卷制。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Herr Lehmann'
