UNION ALL SELECT 'Herr Lehmann', 'ar', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('وبراندي التفاح، بحسب Dein Dorfladen؛' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Herr Lehmann'
