SELECT (SELECT COUNT(*) FROM `translation_status` t JOIN `brands` b ON b.`name` = t.`entite_id` AND t.`entite` = 'brands'
         WHERE t.`source_hash` <> SHA1(CASE t.`champ` WHEN 'history' THEN b.`history` ELSE b.`gamme` END)
           AND t.`champ` IN ('history', 'gamme') AND b.`name` IN ('Holt''s Cigar Company','Helvada','Herr Lehmann')) = 0 AS sceaux_a_jour,
       (SELECT SUM(CHAR_LENGTH(`detail`) >= 255) = 0 FROM `moderation_log` WHERE `acteur_nom` = 'migration 257') AS journal_non_tronque;
